sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float redGamma;
uniform float greenGamma;
uniform float blueGamma;

half4 main(float2 coord) {
    half4 col = image.eval(coord);
    if (col.a < 1e-3) return half4(0);
    float3 rgb = float3(col.rgb / col.a);
    float3 g = float3(max(redGamma, 0.01), max(greenGamma, 0.01), max(blueGamma, 0.01));
    float3 outRgb = pow(max(rgb, float3(0.0)), 1.0 / g);
    return half4(half3(clamp(outRgb, 0.0, 1.0)) * col.a, col.a);
}
